// Minimal, XSS-safe Markdown renderer for assistant output.
//
// WHY HAND-ROLLED: Ask Anvil rendered replies as plain text with
// `white-space: pre-wrap`, so the model's Markdown arrived literally — tables
// showed as rows of pipes, **bold** kept its asterisks. Anvil's CSP is
// `script-src 'self'`, so a CDN parser is out, and pulling in a full Markdown
// stack (plus a sanitiser) for the handful of constructs an ERP answer
// actually uses is a lot of bundle and a lot of attack surface.
//
// SAFETY MODEL — the important part. Assistant text is UNTRUSTED: it is model
// output that can quote customer documents, which can themselves contain HTML
// or a javascript: URL. So:
//   1. EVERY input character is HTML-escaped FIRST. Nothing the model emits can
//      ever become a live tag.
//   2. Only then do we substitute a fixed set of tags we generate ourselves.
//   3. Link hrefs are whitelisted to http/https/mailto; anything else renders
//      as plain text rather than an anchor.
// Because escaping precedes generation, the output can only contain the tags
// in this file.

const ESCAPES: Record<string, string> = {
  "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;",
};

export const escapeHtml = (s: string): string =>
  String(s ?? "").replace(/[&<>"']/g, (c) => ESCAPES[c]);

// Only these schemes may become an anchor. A javascript:/data: URL renders as
// text — visible, but inert.
const SAFE_HREF = /^(https?:\/\/|mailto:)/i;

// Inline formatting. Input is ALREADY escaped, so the regexes here operate on
// escaped text and emit our own tags.
const inline = (escaped: string): string => {
  let s = escaped;
  // `code` first, so its contents are not further transformed.
  const codes: string[] = [];
  s = s.replace(/`([^`]+)`/g, (_m, c) => {
    codes.push(c);
    return "�CODE" + (codes.length - 1) + "�";
  });
  // [text](href)
  s = s.replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, (m, text, href) => {
    // href is escaped text; &amp; must be read back as & for the scheme test.
    const raw = String(href).replace(/&amp;/g, "&");
    if (!SAFE_HREF.test(raw)) return m;
    return '<a href="' + href + '" target="_blank" rel="noopener noreferrer">' + text + "</a>";
  });
  s = s.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
  s = s.replace(/(^|[^*])\*([^*\n]+)\*/g, "$1<em>$2</em>");
  s = s.replace(/�CODE(\d+)�/g, (_m, i) => "<code>" + codes[Number(i)] + "</code>");
  return s;
};

const isTableSeparator = (line: string) => /^\s*\|?[\s:|-]+\|[\s:|-]*$/.test(line) && line.includes("-");

const splitRow = (line: string) =>
  line.trim().replace(/^\||\|$/g, "").split("|").map((c) => c.trim());

// Public: Markdown -> a safe HTML string.
export const renderMarkdown = (src: string): string => {
  const lines = String(src ?? "").replace(/\r\n/g, "\n").split("\n");
  const out: string[] = [];
  let i = 0;
  let para: string[] = [];

  const flushPara = () => {
    if (!para.length) return;
    out.push("<p>" + inline(escapeHtml(para.join(" "))) + "</p>");
    para = [];
  };

  while (i < lines.length) {
    const line = lines[i];

    // Fenced code block — contents escaped, never interpreted.
    if (/^\s*```/.test(line)) {
      flushPara();
      const buf: string[] = [];
      i++;
      while (i < lines.length && !/^\s*```/.test(lines[i])) { buf.push(lines[i]); i++; }
      i++;
      out.push("<pre><code>" + escapeHtml(buf.join("\n")) + "</code></pre>");
      continue;
    }

    // Table: a header row followed by a |---|---| separator.
    if (line.includes("|") && i + 1 < lines.length && isTableSeparator(lines[i + 1])) {
      flushPara();
      const head = splitRow(line);
      i += 2;
      const body: string[][] = [];
      while (i < lines.length && lines[i].includes("|") && lines[i].trim()) {
        body.push(splitRow(lines[i]));
        i++;
      }
      out.push(
        '<div class="md-table-wrap"><table class="md-table"><thead><tr>'
        + head.map((h) => "<th>" + inline(escapeHtml(h)) + "</th>").join("")
        + "</tr></thead><tbody>"
        + body.map((r) => "<tr>" + r.map((c) => "<td>" + inline(escapeHtml(c)) + "</td>").join("") + "</tr>").join("")
        + "</tbody></table></div>",
      );
      continue;
    }

    // Heading
    const h = line.match(/^\s*(#{1,4})\s+(.*)$/);
    if (h) {
      flushPara();
      const level = Math.min(6, h[1].length + 2);   // # -> h3, so it never outranks the page title
      out.push("<h" + level + ">" + inline(escapeHtml(h[2])) + "</h" + level + ">");
      i++;
      continue;
    }

    // Lists (consecutive bullet or ordered items)
    if (/^\s*([-*+]|\d+\.)\s+/.test(line)) {
      flushPara();
      const ordered = /^\s*\d+\.\s+/.test(line);
      const items: string[] = [];
      while (i < lines.length && /^\s*([-*+]|\d+\.)\s+/.test(lines[i])) {
        items.push(lines[i].replace(/^\s*([-*+]|\d+\.)\s+/, ""));
        i++;
      }
      const tag = ordered ? "ol" : "ul";
      out.push("<" + tag + ">" + items.map((t) => "<li>" + inline(escapeHtml(t)) + "</li>").join("") + "</" + tag + ">");
      continue;
    }

    if (!line.trim()) { flushPara(); i++; continue; }

    para.push(line.trim());
    i++;
  }
  flushPara();
  return out.join("");
};
